// Notification Lead Time Timeline
// CANVAS_HEIGHT: 630
//
// Generated by scripts/build-timeline-sim.py from
// scripts/sim-timelines/notification-lead-time-timeline.json -- edit the data file, not this.

const CLASS_COLORS = {
    "hub": [
        "#F5A623",
        "#B87B12",
        "#000000"
    ],
    "node": [
        "#4A90D9",
        "#2E6BA8",
        "#FFFFFF"
    ],
    "resolve": [
        "#3E9E6E",
        "#256E4A",
        "#FFFFFF"
    ],
    "danger": [
        "#D64545",
        "#8F2B2B",
        "#FFFFFF"
    ],
    "wait": [
        "#8E7CC3",
        "#5B4B8A",
        "#FFFFFF"
    ],
    "remediate": [
        "#E8833A",
        "#A85718",
        "#FFFFFF"
    ],
    "neutral": [
        "#5B7186",
        "#33475B",
        "#FFFFFF"
    ]
};

const itemData = [
    {
        "id": "first",
        "at": -14,
        "cls": "node",
        "label": "First reminder",
        "hint": "Day −14 — gives families time to plan",
        "detail": [
            [
                "When",
                "Fourteen days before."
            ],
            [
                "Why then",
                "This is the reminder that changes what a family does. Two weeks is long enough to move a shift, arrange a lift, or say no early enough that you can offer the place to somebody else."
            ],
            [
                "Sample message",
                "\"Coding Club showcase is on Tuesday 14 March, 4–6pm, in the library. Families welcome. Reply if you can come so we know numbers.\""
            ],
            [
                "What it must contain",
                "Date, time, place, and what is being asked of the reader. A reminder without an ask is an announcement."
            ]
        ]
    },
    {
        "id": "second",
        "at": -1,
        "cls": "hub",
        "label": "Second reminder",
        "hint": "Day −1 — a short, same-day-relevant nudge",
        "detail": [
            [
                "When",
                "The day before."
            ],
            [
                "Why then",
                "This one does not change plans, it prevents forgetting — so it should be short and carry only what somebody needs in the next 24 hours."
            ],
            [
                "Sample message",
                "\"Reminder: showcase tomorrow, 4pm, library. Bring your project if you'd like to show it.\""
            ],
            [
                "Why not the morning of",
                "Too late to arrange anything, and it lands while people are already committed elsewhere. The day before is the last point at which a reminder is still actionable."
            ]
        ]
    },
    {
        "id": "event",
        "at": 0,
        "cls": "resolve",
        "label": "Event day",
        "hint": "What two touches buy over one",
        "detail": [
            [
                "The pattern",
                "Two reminders, doing two different jobs. The first buys planning time; the second prevents forgetting. A single reminder can only do one of those."
            ],
            [
                "Which single reminder is worse",
                "Both, differently. Only the 14-day one and people plan to come and forget. Only the day-before one and people remember but cannot rearrange."
            ],
            [
                "Why not three",
                "A third reminder does not add a third job — it repeats one of the first two, and it is the point at which recipients start filtering the club's mail. Two touches, two purposes, stop."
            ],
            [
                "The honest caveat",
                "This cadence is a sensible default, not a measured result for your club. Track replies against reminders for a term and you will know your own numbers."
            ]
        ]
    }
];
const TICKS = {
    "-14": "14 days before",
    "-10": "10 days",
    "-7": "1 week",
    "-3": "3 days",
    "0": "Event day"
};
const MARKER = null;
const WINDOW_MIN = -17;
const WINDOW_MAX = 3;
const TIMELINE_HEIGHT = 200;

let timeline, items;

// vis-timeline works in dates, and none of these timelines is about dates: one
// counts years since founding, one counts weeks of a semester, one counts down
// to an event. Ordinal positions are mapped onto a fixed epoch and the axis is
// relabelled from TICKS, so the reader never sees a calendar.
const EPOCH = Date.UTC(2000, 0, 1);
const UNIT = 24 * 60 * 60 * 1000;          // one ordinal step = one day

function toDate(n) { return new Date(EPOCH + n * UNIT); }
// vis-timeline hands the axis formatter a Moment and the move handler a Date.
// valueOf() is the one accessor both have.
function toOrdinal(d) { return Math.round((d.valueOf() - EPOCH) / UNIT); }

function styleFor(cls) {
    const c = CLASS_COLORS[cls] || CLASS_COLORS.neutral;
    return 'background-color:' + c[0] + '; border-color:' + c[1] +
           '; color:' + c[2] + ';';
}

function buildItems() {
    const out = itemData.map(it => {
        const o = {
            id: it.id,
            content: it.label,
            start: toDate(it.at),
            type: it.end !== undefined ? 'range' : 'box',
            style: styleFor(it.cls),
            title: it.hint || it.label,
            editable: false
        };
        // Only set `end` when there really is one. vis-timeline's DataSet
        // type-converts every key that is present, so an explicit
        // `end: undefined` makes it call getTime() on undefined and the
        // whole timeline fails to draw.
        if (it.end !== undefined) o.end = toDate(it.end);
        return o;
    });
    if (MARKER) {
        out.push({
            id: '__marker',
            content: MARKER.label,
            start: toDate(MARKER.at),
            type: 'point',
            className: 'marker',
            // The only draggable thing on the timeline: the reader's own
            // bookmark. Everything else is fixed so a stray drag cannot
            // rearrange the content.
            editable: { updateTime: true, updateGroup: false, remove: false }
        });
    }
    return out;
}

// The window is fixed -- no panning, no zooming -- so position maps to pixels
// linearly across the centre panel, and a tick can be placed exactly on the
// gridline it names.
function layoutTicks() {
    const host = document.getElementById('axis-ticks');
    const panel = document.querySelector('#timeline .vis-panel.vis-center');
    if (!host || !panel) return;
    const hr = host.getBoundingClientRect();
    const pr = panel.getBoundingClientRect();
    const span = WINDOW_MAX - WINDOW_MIN;
    host.innerHTML = '';
    Object.keys(TICKS).forEach(function (k) {
        const frac = (Number(k) - WINDOW_MIN) / span;
        const el = document.createElement('span');
        el.textContent = TICKS[k];
        el.style.left = ((pr.left - hr.left) + frac * pr.width) + 'px';
        host.appendChild(el);
    });
}

function initializeTimeline() {
    items = new vis.DataSet(buildItems());

    const options = {
        height: TIMELINE_HEIGHT + 'px',
        min: toDate(WINDOW_MIN),
        max: toDate(WINDOW_MAX),
        start: toDate(WINDOW_MIN),
        end: toDate(WINDOW_MAX),
        // Locked window: there is nothing outside the range, so panning or
        // zooming out of it only loses the reader.
        zoomable: false,
        moveable: false,
        selectable: true,
        stack: true,
        align: 'center',
        margin: { item: 12, axis: 18 },
        orientation: { axis: 'bottom', item: 'top' },
        // One tick per ordinal position. Left to itself vis picks a round
        // step -- 4 days across a 19-day window -- and any label whose
        // position is not a multiple of that step silently never renders.
        // Ticking every position and returning '' for the unlabelled ones
        // puts the TICKS map in charge of what the reader sees.
        timeAxis: { scale: 'day', step: 1 },
        editable: { updateTime: true, add: false, remove: false },
        onMove: function (item, callback) {
            // Snap the bookmark to whole positions, and never let it leave the
            // range.
            let n = Math.round(toOrdinal(item.start));
            n = Math.max(Math.ceil(WINDOW_MIN), Math.min(Math.floor(WINDOW_MAX), n));
            item.start = toDate(n);
            callback(item);
        },
        format: {
            minorLabels: function () { return ''; },
            majorLabels: function () { return ''; }
        }
    };

    const container = document.getElementById('timeline');
    timeline = new vis.Timeline(container, items, options);
    timeline.on('select', onSelect);
    timeline.on('changed', layoutTicks);
    window.addEventListener('resize', layoutTicks);
    layoutTicks();
}

function onSelect(props) {
    const id = props.items && props.items[0];
    if (!id || id === '__marker') { clearInfo(); return; }
    const it = itemData.find(d => d.id === id);
    if (!it) return;
    const body = (it.detail || [])
        .map(pair => '<p><strong>' + pair[0] + ':</strong> ' + pair[1] + '</p>')
        .join('');
    document.getElementById('info-content').innerHTML =
        '<div class="info-label" style="color:' +
        (CLASS_COLORS[it.cls] || CLASS_COLORS.neutral)[1] + '">' +
        it.label.replace(/<[^>]*>/g, ' ') + '</div>' + body;
}

function clearInfo() {
    document.getElementById('info-content').innerHTML =
        '<p class="info-placeholder">Click either reminder for a sample message and why it goes out when it does. Click Event Day for what the two-touch pattern actually buys.</p>';
}

function reset() {
    timeline.destroy();
    initializeTimeline();
    clearInfo();
}

document.addEventListener('DOMContentLoaded', function () {
    initializeTimeline();
    document.getElementById('reset-btn').addEventListener('click', reset);
});
